def load_nbt_fixture(name):
    return json.loads(
        (HERE / "fixtures" / name).read_text(encoding="utf-8"))


def shulker_item_tag_document(block_entity_document):
    block_entity = block_entity_document["tag"]
    value = {"BlockEntityTag": block_entity}
    custom_name = block_entity["value"].get("CustomName")
    if custom_name is not None:
        value["display"] = {
            "type": "compound",
            "value": {"Name": custom_name},
        }
    return {
        "name": "",
        "tag": {"type": "compound", "value": value},
    }


