    if case.behavior == "xp_pickup":
        initial_orbs = [
            entity for entity in before.get("entities", [])
            if entity.get("type") == "EntityXPOrb"
        ]
        baseline_level = int(before["player"]["xp_level"])
        baseline_fraction = float(before["player"]["xp_frac"])
        failures = []
        evidence = []
        fixture_valid = (
            baseline_level == 0
            and baseline_fraction == 0.0
            and len(initial_orbs) == 1
            and initial_orbs[0].get("value") == 5
            and initial_orbs[0].get("age") == 0
            and initial_orbs[0].get("pickup_delay") == 0
        )
        if not fixture_valid:
            failures.append("java: invalid pre-tick XP fixture")
        for label, rows in (("java", java_rows), ("magma", magma_rows)):
            orb_rows = []
            award_ticks = []
            for row in rows:
                orbs = [
                    entity for entity in row.get("entities", [])
                    if entity.get("type") == "EntityXPOrb"
                ]
                if orbs:
                    orb_rows.append((int(row["tick"]), orbs))
                if (
                    int(row["player"]["xp_level"]) != baseline_level
                    or abs(float(row["player"]["xp_frac"])
                           - baseline_fraction) > 1e-6
                ):
                    award_ticks.append(int(row["tick"]))
            ages = [
                int(orbs[0]["age"])
                for _, orbs in orb_rows if len(orbs) == 1
            ]
            xs = [
                float(orbs[0]["x"])
                for _, orbs in orb_rows if len(orbs) == 1
            ]
            first_award = award_ticks[0] if award_ticks else None
            valid = (
                len(rows) >= 10
                and [tick for tick, _ in orb_rows] == list(range(8))
                and all(len(orbs) == 1 for _, orbs in orb_rows)
                and ages == list(range(1, 9))
                and all(xs[i + 1] < xs[i] for i in range(len(xs) - 1))
                and first_award == 8
                and int(rows[8]["player"]["xp_level"]) == 0
                and abs(float(rows[8]["player"]["xp_frac"]) - 5.0 / 7.0)
                    <= 1e-6
                and all(
                    not any(
                        entity.get("type") == "EntityXPOrb"
                        for entity in row.get("entities", [])
                    )
                    for row in rows[8:]
                )
            )
            evidence.append(
                f"{label}:orb_ticks=0..7,ages=1..8,"
                f"pickup_tick={first_award},"
                f"xp={float(rows[8]['player']['xp_frac']):.8f}"
                if len(rows) > 8 else
                f"{label}:trace_too_short"
            )
            if not valid:
                failures.append(
                    f"{label}: attraction, removal, or XP award boundary not observed")
        return (
            ("fail", "; ".join(failures))
            if failures else
            ("pass", "; ".join(evidence))
        )

    if case.behavior in ("potion_speed", "potion_slowness"):
        speed = case.behavior == "potion_speed"
        effect_id = 1 if speed else 2
        effect_name = "Speed II" if speed else "Slowness II"
        expected_before = [{"id": effect_id, "amp": 1, "dur": 6}]
        failures = []
        evidence = []
        if before["player"].get("potions") != expected_before:
            failures.append(f"java: invalid pre-tick {effect_name} fixture")
        for label, rows in (("java", java_rows), ("magma", magma_rows)):
            potion_rows = [row["player"].get("potions") for row in rows]
            expected = (
                [[{"id": effect_id, "amp": 1, "dur": duration}]
                 for duration in range(5, 0, -1)]
                + [[] for _ in range(max(0, len(rows) - 5))]
            )
            steps = [
                math.hypot(
                    float(rows[i]["player"]["x"])
                        - float(rows[i - 1]["player"]["x"]),
                    float(rows[i]["player"]["z"])
                        - float(rows[i - 1]["player"]["z"]),
                )
                for i in range(1, len(rows))
            ]
            active_step = max(steps[:4]) if steps else 0.0
            settled_step = max(steps[-3:]) if steps else 0.0
            derived_speed = (
                len(steps) >= 10
                and (
                    active_step > settled_step * 1.15 if speed else
                    active_step < settled_step * 0.9
                )
            )
            valid = (
                len(rows) >= 12
                and potion_rows == expected
                and derived_speed
            )
            evidence.append(
                f"{label}:dur=5..1,removed=5,"
                f"active_step={active_step:.6f},"
                f"settled_step={settled_step:.6f}"
            )
            if not valid:
                failures.append(
                    f"{label}: {effect_name} duration, expiry, or modifier "
                    "not observed")
        return (
            ("fail", "; ".join(failures))
            if failures else
            ("pass", "; ".join(evidence))
        )

