        try:
            box = [
                int(value)
                for value in (case_out / "block_box.txt").read_text().split()
            ]
            before_raw = (case_out / "java_blocks_before.bin").read_bytes()
            java_raw = (case_out / "java_blocks.bin").read_bytes()
            magma_raw = (case_out / "c_runtime_blocks.bin").read_bytes()
            count = len(before_raw) // 2
            before_cells = struct.unpack(f"<{count}H", before_raw)
            java_cells = struct.unpack(f"<{count}H", java_raw)
            magma_cells = struct.unpack(f"<{count}H", magma_raw)
            x0, y0, z0, x1, _y1, z1 = box
            nx, nz = x1 - x0 + 1, z1 - z0 + 1
            mutations = {}
            for index, (old, new) in enumerate(zip(before_cells, java_cells)):
                if old == new:
                    continue
                x = x0 + index % nx
                yz = index // nx
                z = z0 + yz % nz
                y = y0 + yz // nz
                mutations[(x, y, z)] = (old, new)
            expected = {(9, 83, 8): (0, 51 << 4)}
            if mutations != expected or magma_cells != java_cells:
                failures.append(
                    "raw: expected one exact air-to-fire crystal mutation")
            else:
                evidence.append("raw:(9,83,8) air->fire")
        except (OSError, ValueError, struct.error) as exc:
            failures.append(
                f"raw: could not validate End crystal fire: {exc}")
        return (
            ("fail", "; ".join(failures))
            if failures else
            ("pass", "; ".join(evidence))
        )

