    if case.behavior in (
            "tnt_explosion_player_open_air",
            "tnt_explosion_player_obstructed",
            "tnt_explosion_player_resistance",
            "tnt_explosion_player_armor",
            "tnt_explosion_player_blast_protection",
            "tnt_explosion_player_blast_protection_resistance"):
        failures = []
        evidence = []
        expected_world_seed = None
        expected = None
        expected_armor_after = None
        open_air = case.behavior != "tnt_explosion_player_obstructed"
        resistance = case.behavior in (
            "tnt_explosion_player_resistance",
            "tnt_explosion_player_blast_protection_resistance",
        )
        armored = case.behavior in (
            "tnt_explosion_player_armor",
            "tnt_explosion_player_blast_protection",
            "tnt_explosion_player_blast_protection_resistance",
        )
        blast_protection = case.behavior in (
            "tnt_explosion_player_blast_protection",
            "tnt_explosion_player_blast_protection_resistance",
        )
        combined_defense = (
            case.behavior
            == "tnt_explosion_player_blast_protection_resistance")
        exposure_label = (
            "open-air armor + Resistance I + Blast Protection IV"
            if combined_defense
            else "open-air Resistance I" if resistance
            else "open-air Blast Protection IV" if blast_protection
            else "open-air diamond chestplate" if armored
            else "open-air" if open_air else "obstructed"
        )
        try:
            detonation = java_rows[0]["diagnostics"]["tnt_detonation"]
            f32 = lambda value: struct.unpack(
                "<f", struct.pack("<f", value))[0]
            density = float(detonation["density"])
            if open_air and not math.isclose(
                    density, 1.0, rel_tol=0.0, abs_tol=0.0):
                failures.append("oracle: player exposure is not open-air")
            if not open_air and not math.isclose(
                    density, f32(8.0 / 15.0),
                    rel_tol=0.0, abs_tol=1.0e-8):
                failures.append(
                    "oracle: player exposure is not exact 24/45 clear")
            before_player = before["player"]
            packet_x = float(detonation["packet_x"])
            packet_z = float(detonation["packet_z"])
            quantized_x = int(packet_x * 8000.0) / 8000.0
            quantized_z = int(packet_z * 8000.0) / 8000.0
            friction = f32(f32(0.6) * f32(0.91))
            damage = int(detonation["damage"])
            health_damage = float(damage)
            if armored:
                toughness_scale = f32(2.0 + f32(2.0 / 4.0))
                armor_floor = f32(
                    8.0 - f32(f32(health_damage) / toughness_scale))
                armor_floor = max(
                    f32(8.0 * 0.2), min(20.0, armor_floor))
                health_damage = f32(
                    f32(health_damage)
                    * f32(1.0 - f32(armor_floor / 25.0)))
            if resistance:
                health_damage = f32(f32(health_damage * 20.0) / 25.0)
            if blast_protection:
                health_damage = f32(
                    health_damage * f32(1.0 - f32(8.0 / 25.0)))
            expected = {
                "x": float(before_player["x"]) + quantized_x,
                "y": float(before_player["y"]),
                "z": float(before_player["z"]) + quantized_z,
                "vx": quantized_x * friction,
                "vy": float(before_player["vy"]),
                "vz": quantized_z * friction,
                "health": f32(
                    f32(float(before_player["health"])) - health_damage),
                "food_exhaustion":
                    float(before_player["food_exhaustion"]) + 0.1,
                "food_timer": int(before_player["food_timer"]) + 1,
                "hurt_time": 9,
            }
            expected_world_seed = int(
                before["world_rng"]["java_seed48"])
            for _draw in range(1354):
                expected_world_seed = (
                    expected_world_seed * 0x5DEECE66D + 0xB
                ) & ((1 << 48) - 1)
            evidence.append(
                f"oracle:density={density},raw-damage={damage},"
                f"health-damage={health_damage},packet-x={packet_x},"
                f"quantized-x={quantized_x}")
            if armored:
                enchantments = [[3, 4]] if blast_protection else []
                expected_armor_before = [{
                    "slot": 38, "id": 311, "count": 1, "meta": 0,
                    "enchants": enchantments,
                }]
                expected_armor_after = [{
                    "slot": 38, "id": 311, "count": 1, "meta": 1,
                    "enchants": enchantments,
                }]
                if before.get("diagnostics", {}).get(
                        "server_armor") != expected_armor_before:
                    failures.append(
                        "oracle: armor fixture is not exact before detonation")
        except (IndexError, KeyError, TypeError, ValueError) as exc:
            failures.append(
                f"oracle: could not derive player blast boundary: {exc}")
        for label, rows in (("java", java_rows), ("magma", magma_rows)):
            row = rows[0] if len(rows) == 1 else {}
            player = row.get("player", {})
            primed = [
                entity for entity in row.get("entities", [])
                if entity.get("type") == "EntityTNTPrimed"
            ]
            valid = expected is not None and not primed
            response_fields = ("x", "y", "z", "vx", "vy", "vz")
            applied = expected is not None and all(
                math.isclose(
                    float(player.get(field, math.inf)), expected[field],
                    rel_tol=1.0e-7, abs_tol=1.0e-7)
                for field in response_fields
            )
            deferred = (
                (not open_air or resistance or armored)
                and label == "java" and all(
                math.isclose(
                    float(player.get(field, math.inf)),
                    float(before["player"][field]),
                    rel_tol=1.0e-7, abs_tol=1.0e-7)
                for field in response_fields
                )
            )
            valid = valid and (applied or deferred)
            for field in ("health", "food_exhaustion"):
                valid = valid and math.isclose(
                    float(player.get(field, math.inf)), expected[field],
                    rel_tol=1.0e-7, abs_tol=1.0e-7)
            valid = valid and (
                int(player.get("food_timer", -1))
                    == expected["food_timer"]
                and int(player.get("hurt_time", -1))
                    == expected["hurt_time"]
            )
            if armored:
                valid = valid and row.get("diagnostics", {}).get(
                    "server_armor") == expected_armor_after
            if label == "magma":
                valid = valid and int(
                    row.get("world_rng", {}).get("java_seed48", -1)
                ) == expected_world_seed
                if not open_air or resistance or armored:
                    java_diagnostics = java_rows[0].get("diagnostics", {})
                    magma_diagnostics = row.get("diagnostics", {})
                    for field in (
                            "server_x", "server_y", "server_z",
                            "server_vx", "server_vy", "server_vz"):
                        valid = valid and math.isclose(
                            float(magma_diagnostics.get(field, math.inf)),
                            float(java_diagnostics.get(field, math.inf)),
                            rel_tol=1.0e-7, abs_tol=1.0e-7)
            if not valid:
                failures.append(
                    f"{label}: exact {exposure_label} blast response absent")
            else:
                evidence.append(
                    f"{label}:health={player.get('health')},"
                    f"x={player.get('x')},vx={player.get('vx')},hurt=9,"
                    f"packet={'applied' if applied else 'deferred'}")
        try:
            box = [
                int(value)
                for value in (case_out / "block_box.txt").read_text().split()
            ]
            before_raw = (case_out / "java_blocks_before.bin").read_bytes()
            java_raw = (case_out / "java_blocks.bin").read_bytes()
            magma_raw = (case_out / "c_runtime_blocks.bin").read_bytes()
            count = len(before_raw) // 2
            before_cells = struct.unpack(f"<{count}H", before_raw)
            java_cells = struct.unpack(f"<{count}H", java_raw)
            magma_cells = struct.unpack(f"<{count}H", magma_raw)
            x0, y0, z0, x1, _y1, z1 = box
            nx, nz = x1 - x0 + 1, z1 - z0 + 1
            mutations = {}
            for index, (old, new) in enumerate(zip(before_cells, java_cells)):
                if old == new:
                    continue
                x = x0 + index % nx
                yz = index // nx
                z = z0 + yz % nz
                y = y0 + yz // nz
                mutations[(x, y, z)] = (old, new)
            mutation_shape_valid = bool(mutations) and (
                not open_air or all(
                    y == 77 and old == (1 << 4) and new == 0
                    for (_x, y, _z), (old, new) in mutations.items()
                )
            )
            if not mutation_shape_valid or magma_cells != java_cells:
                failures.append(
                    f"raw: {exposure_label} blast mutation differs")
            else:
                evidence.append(
                    f"raw:{len(mutations)} exact {exposure_label} removal(s)")
        except (OSError, ValueError, struct.error) as exc:
            failures.append(
                f"raw: could not validate {exposure_label} blast mutation: "
                f"{exc}")
        return (
            ("fail", "; ".join(failures))
            if failures else
            ("pass", "; ".join(evidence))
        )

