    # A directly destroyed reed drops first, then its air write recursively
    # destroys the contiguous column above it. Generate extension/pull and
    # lower/middle expectations together so their raw-volume contract cannot
    # drift apart.
    for block_name, block_id, drop_item in (("reed", 83, 338),):
        for level, drop_count in (("lower", 3), ("middle", 2)):
            for action in ("extension", "pull"):
                is_pull = action == "pull"
                column_x = 13 if is_pull else 14
                origin_x = 14 if is_pull else 13
                destination_x = 13 if is_pull else 14
                stem = (
                    f"redstone_{'sticky_' if is_pull else ''}piston_east_"
                    f"slime_north_stone_{block_name}_{level}_{action}")
                drop_seed = (
                    0xEE85F453C1E7 if drop_count == 3
                    else 0x86D91B38BCB3)
                target_meta = 3 if level == "lower" else 7
                column_mutations = {
                    (column_x, 79, 7): (
                        (block_id << 4) | target_meta, (36 << 4) | 5),
                    (column_x, 80, 7): (
                        (block_id << 4) | (7 if level == "lower" else 12),
                        0),
                }
                if level == "lower":
                    column_mutations[(column_x, 81, 7)] = (
                        (block_id << 4) | 12, 0)
                for phase, rows in (("start", 1), ("settled", 3)):
                    if is_pull:
                        mutations = {
                            (12, 79, 8): (
                                (29 << 4) | 13,
                                (36 << 4) | 13 if phase == "start"
                                else (29 << 4) | 5),
                            (13, 79, 8): (
                                (34 << 4) | 13,
                                (36 << 4) | 5 if phase == "start"
                                else 165 << 4),
                            (14, 79, 8): (165 << 4, 0),
                            (origin_x, 79, 7): (1 << 4, 0),
                            (12, 79, 9): (152 << 4, 0),
                        }
                    else:
                        mutations = {
                            (12, 79, 8): (
                                (33 << 4) | 5, (33 << 4) | 13),
                            (13, 79, 8): (
                                165 << 4,
                                (36 << 4) | 5 if phase == "start"
                                else (34 << 4) | 5),
                            (14, 79, 8): (
                                0, (36 << 4) | 5 if phase == "start"
                                else 165 << 4),
                            (origin_x, 79, 7): (1 << 4, 0),
                            (12, 79, 9): (0, 152 << 4),
                        }
                    mutations.update(column_mutations)
                    if phase == "settled":
                        mutations[(destination_x, 79, 7)] = (
                            (block_id << 4) | target_meta, 1 << 4)
                    piston_slime_specs[f"{stem}_{phase}"] = {
                        "rows": rows,
                        "drop_item": drop_item,
                        "drop_count": drop_count,
                        "world_seed_after": drop_seed,
                        "mutations": mutations,
                    }
    # A cactus cannot validly touch the terminal side stone before the move.
    # The reachable topology starts diagonal to it: block 36 remains
    # non-solid during motion, then the settled stone invalidates the column
    # on the third observation. The callback still owns bottom-up drops, but
    # they occur after the controlled-input cursor window.
    for level, drop_count in (("lower", 3), ("middle", 2)):
        for action in ("extension", "pull"):
            is_pull = action == "pull"
            column_x = 13 if is_pull else 14
            origin_x = 14 if is_pull else 13
            destination_x = 13 if is_pull else 14
            stem = (
                f"redstone_{'sticky_' if is_pull else ''}piston_east_"
                f"slime_north_stone_cactus_{level}_settlement_{action}")
            for phase, rows in (("start", 1), ("settled", 3)):
                if is_pull:
                    mutations = {
                        (12, 79, 8): (
                            (29 << 4) | 13,
                            (36 << 4) | 13 if phase == "start"
                            else (29 << 4) | 5),
                        (13, 79, 8): (
                            (34 << 4) | 13,
                            (36 << 4) | 5 if phase == "start"
                            else 165 << 4),
                        (14, 79, 8): (165 << 4, 0),
                        (origin_x, 79, 7): (1 << 4, 0),
                        (12, 79, 9): (152 << 4, 0),
                    }
                else:
                    mutations = {
                        (12, 79, 8): (
                            (33 << 4) | 5, (33 << 4) | 13),
                        (13, 79, 8): (
                            165 << 4,
                            (36 << 4) | 5 if phase == "start"
                            else (34 << 4) | 5),
                        (14, 79, 8): (
                            0, (36 << 4) | 5 if phase == "start"
                            else 165 << 4),
                        (origin_x, 79, 7): (1 << 4, 0),
                        (12, 79, 9): (0, 152 << 4),
                    }
                if phase == "settled":
                    mutations[(destination_x, 79, 7)] = (0, 1 << 4)
                    target_meta = 3 if level == "lower" else 7
                    mutations[(column_x, 79, 6)] = (
                        (81 << 4) | target_meta, 0)
                    mutations[(column_x, 80, 6)] = (
                        (81 << 4) | (7 if level == "lower" else 12), 0)
                    if level == "lower":
                        mutations[(column_x, 81, 6)] = (
                            (81 << 4) | 12, 0)
                else:
                    mutations[(destination_x, 79, 7)] = (
                        0, (36 << 4) | 5)
                spec = {
                    "rows": rows,
                    "drop_count": drop_count if phase == "settled" else 0,
                    "controlled_world_seed_after": 0xB,
                    "mutations": mutations,
                }
                if phase == "settled":
                    spec.update({
                        "drop_item": 81,
                        "controlled_drop_count": 0,
                        "drop_row": -1,
                        "drop_age": 0,
                        "drop_pickup_delay": 10,
                    })
                piston_slime_specs[f"{stem}_{phase}"] = spec
    if case.behavior in piston_slime_specs:
        spec = piston_slime_specs[case.behavior]
        failures = []
        evidence = []
        if (len(java_rows) != spec["rows"]
                or len(magma_rows) != spec["rows"]):
            failures.append(
                f"trace: slime fixture requires {spec['rows']} rows")
        for label, rows in (("java", java_rows), ("magma", magma_rows)):
            if not rows:
                continue
            controlled = rows[0].get("controlled_input") or {}
            before = controlled.get("before") or {}
            before_rng = before.get("world_rng") or {}
            after_rng = controlled.get("world_rng") or {}
            drop_item = spec.get("drop_item")
            drop_meta = spec.get("drop_meta", 0)
            drop_count = spec.get(
                "drop_count", 1 if drop_item is not None else 0)
            controlled_drop_count = spec.get(
                "controlled_drop_count", drop_count)
            expected_seed = spec.get(
                "controlled_world_seed_after", spec.get(
                "world_seed_after",
                0x5D5692ACE2BF if drop_count else 0xB)
            )
            before_eid = before.get("entity_id_cursor")
            expected_eid = (
                before_eid + controlled_drop_count
                if isinstance(before_eid, int)
                else before_eid)
            if (before_rng.get("java_seed48") != 0
                    or after_rng.get("java_seed48") != expected_seed
                    or controlled.get("entity_id_cursor")
                        != expected_eid):
                failures.append(
                    f"{label}: slime transition sound/entity cursor differs")
            else:
                evidence.append(
                    f"{label}:world_seed48={expected_seed};"
                    f"controlled_eid_delta={controlled_drop_count}")
            if drop_item is not None:
                drop_row = rows[spec.get("drop_row", 0)]
                if controlled_drop_count == drop_count:
                    dropped = [
                        entity for entity in (drop_row.get("entities") or [])
                        if (isinstance(before_eid, int)
                            and before_eid <= entity.get("eid", -1)
                                < before_eid + drop_count)
                    ]
                else:
                    dropped = [
                        entity for entity in (drop_row.get("entities") or [])
                        if entity.get("type") == "EntityItem"
                        and abs(float(entity.get("dx", 1.0e9))) <= 8.0
                        and abs(float(entity.get("dy", 1.0e9))) <= 4.0
                        and abs(float(entity.get("dz", 1.0e9))) <= 4.0
                    ]
                expected_age = spec.get("drop_age", 1)
                expected_pickup = spec.get("drop_pickup_delay", 9)
                if (len(dropped) != drop_count
                        or any(
                            entity.get("type") != "EntityItem"
                            or entity.get("item") != drop_item
                            or entity.get("count") != 1
                            or entity.get("meta") != drop_meta
                            or entity.get("age") != expected_age
                            or entity.get("pickup_delay") != expected_pickup
                            for entity in dropped)):
                    failures.append(
                        f"{label}: slime terminal drop state differs")
                else:
                    evidence.append(
                        f"{label}:{drop_count} item {drop_item}:{drop_meta} "
                        f"age={expected_age}/pickup={expected_pickup} exact")
            if any(row.get("scheduled_ticks") for row in rows):
                failures.append(
                    f"{label}: slime transition leaked scheduled ticks")
            else:
                evidence.append(f"{label}:scheduled queue empty")
        try:
            box = [
                int(value)
                for value in (case_out / "block_box.txt").read_text().split()
            ]
            before_raw = (case_out / "java_blocks_before.bin").read_bytes()
            java_raw = (case_out / "java_blocks.bin").read_bytes()
            magma_raw = (case_out / "c_runtime_blocks.bin").read_bytes()
            count = len(before_raw) // 2
            before_cells = struct.unpack(f"<{count}H", before_raw)
            java_cells = struct.unpack(f"<{count}H", java_raw)
            x0, y0, z0, x1, _y1, z1 = box
            nx, nz = x1 - x0 + 1, z1 - z0 + 1
            mutations = {}
            for index, (old, new) in enumerate(
                    zip(before_cells, java_cells)):
                if old == new:
                    continue
                x = x0 + index % nx
                yz = index // nx
                z = z0 + yz % nz
                y = y0 + yz // nz
                mutations[(x, y, z)] = (old, new)
            if mutations != spec["mutations"]:
                failures.append(
                    "java: exact slime/head/side-stone mutations differ")
            else:
                evidence.append("java:6 exact slime-structure mutations")
            if magma_raw != java_raw:
                failures.append("magma: raw slime structure differs")
            else:
                evidence.append("magma:raw slime structure exact")
        except (OSError, ValueError, struct.error) as exc:
            failures.append(
                f"raw: could not validate slime transition: {exc}")
        return (
            ("fail", "; ".join(failures))
            if failures else
            ("pass", "; ".join(evidence))
        )

