    sticky_direction_delta = {
        "down": (0, -1, 0),
        "up": (0, 1, 0),
        "north": (0, 0, -1),
        "south": (0, 0, 1),
        "west": (-1, 0, 0),
    }
    for direction, (move_x, move_y, move_z) in sticky_direction_delta.items():
        geometry = sticky_retraction_directions[direction]
        facing = geometry["facing"]
        target = (
            geometry["base"][0] + 2 * move_x,
            geometry["base"][1] + 2 * move_y,
            geometry["base"][2] + 2 * move_z,
        )
        for action in ("extension", "pull"):
            for phase, rows in (("start", 1), ("settled", 3)):
                if action == "extension":
                    mutations = {
                        geometry["base"]: (
                            (29 << 4) | facing,
                            (29 << 4) | (facing | 8)),
                        geometry["front"]: (
                            1 << 4,
                            (36 << 4) | (facing | 8)
                            if phase == "start"
                            else (34 << 4) | (facing | 8)),
                        target: (
                            0,
                            (36 << 4) | facing
                            if phase == "start" else 1 << 4),
                        geometry["source"]: (0, 152 << 4),
                    }
                else:
                    mutations = {
                        geometry["base"]: (
                            (29 << 4) | (facing | 8),
                            (36 << 4) | (facing | 8)
                            if phase == "start" else (29 << 4) | facing),
                        geometry["front"]: (
                            (34 << 4) | (facing | 8),
                            (36 << 4) | facing
                            if phase == "start" else 1 << 4),
                        target: (1 << 4, 0),
                        geometry["source"]: (152 << 4, 0),
                    }
                behavior = (
                    f"redstone_sticky_piston_{direction}_one_stone_"
                    f"{action}_{phase}")
                piston_lifecycle_specs[behavior] = {
                    "rows": rows, "mutations": mutations,
                }
    if case.behavior in piston_lifecycle_specs:
        spec = piston_lifecycle_specs[case.behavior]
        failures = []
        evidence = []
        if (len(java_rows) != spec["rows"]
                or len(magma_rows) != spec["rows"]):
            failures.append(
                f"trace: sticky fixture requires {spec['rows']} rows")
        for label, rows in (("java", java_rows), ("magma", magma_rows)):
            if not rows:
                continue
            controlled_rows = spec.get("controlled_rows", 1)
            controlled_row_indices = spec.get(
                "controlled_row_indices", tuple(range(controlled_rows)))
            controlled_sound_draws = spec.get(
                "controlled_sound_draws",
                (True,) * len(controlled_row_indices))
            for input_index, row_index in enumerate(controlled_row_indices):
                controlled = (
                    rows[row_index].get("controlled_input") or {})
                controlled_before = controlled.get("before") or {}
                before_rng = controlled_before.get("world_rng") or {}
                after_rng = controlled.get("world_rng") or {}
                before_seed = before_rng.get("java_seed48")
                if (isinstance(before_seed, int)
                        and controlled_sound_draws[input_index]):
                    expected_seed = (
                        (before_seed * 0x5DEECE66D + 0xB)
                        & ((1 << 48) - 1))
                else:
                    expected_seed = before_seed
                if ((input_index == 0 and before_seed != 0)
                        or after_rng.get("java_seed48") != expected_seed
                        or controlled.get("entity_id_cursor")
                            != controlled_before.get("entity_id_cursor")):
                    failures.append(
                        f"{label}: piston sound/entity transition "
                        f"{row_index} differs")
