    if case.behavior in (
            "sky_light_roof_add", "sky_light_roof_remove",
            "sky_light_roof_chunk_edge"):
        failures = []
        evidence = []
        try:
            box = [
                int(value)
                for value in (case_out / "block_box.txt").read_text().split()
            ]
            cells = math.prod((
                box[3] - box[0] + 1,
                box[4] - box[1] + 1,
                box[5] - box[2] + 1,
            ))
            before_light = (
                case_out / "java_sky_light_before.bin").read_bytes()
            java_light = (case_out / "java_sky_light.bin").read_bytes()
            magma_light = (
                case_out / "c_runtime_sky_light.bin").read_bytes()
            if not all(len(raw) == cells for raw in (
                    before_light, java_light, magma_light)):
                raise ValueError("sky-light dump size differs from box")
            source_x = (
                15 if case.behavior == "sky_light_roof_chunk_edge" else 12
            )
            source = (source_x, 86, 8)
            x0, y0, z0, x1, _y1, z1 = box
            nx, nz = x1 - x0 + 1, z1 - z0 + 1

            def index(pos):
                x, y, z = pos
                return (y - y0) * nx * nz + (z - z0) * nx + x - x0

            column = [index((source_x, y, 8)) for y in range(78, 87)]
            changed = {
                cell for cell, (old, new) in enumerate(
                    zip(before_light, java_light)
                )
                if old != new
            }
            if case.behavior == "sky_light_roof_remove":
                transition_ok = (
                    [before_light[cell] for cell in column]
                    == [14] * 8 + [0]
                    and [java_light[cell] for cell in column] == [15] * 9
                )
                description = (
                    "roof removal restores 8 shadow cells 14->15 and "
                    "source 0->15"
                )
                expected_block = {source: (1 << 4, 0)}
            else:
                transition_ok = (
                    [before_light[cell] for cell in column] == [15] * 9
                    and [java_light[cell] for cell in column]
                    == [14] * 8 + [0]
                )
                description = (
                    "roof insertion changes 8 direct-sky cells 15->14 and "
                    "source 15->0"
                )
                expected_block = {source: (0, 1 << 4)}
            if (
                not transition_ok
                or changed != set(column)
                or java_light != magma_light
            ):
                failures.append(
                    "light: expected exact nine-cell saved-skylight transition"
                )
            else:
                evidence.append(f"light:{description}, full cuboid exact")

            before_raw = (
                case_out / "java_blocks_before.bin").read_bytes()
            java_raw = (case_out / "java_blocks.bin").read_bytes()
            magma_raw = (
                case_out / "c_runtime_blocks.bin").read_bytes()
            count = len(before_raw) // 2
            before_cells = struct.unpack(f"<{count}H", before_raw)
            java_cells = struct.unpack(f"<{count}H", java_raw)
            magma_cells = struct.unpack(f"<{count}H", magma_raw)
            mutations = {}
            for cell, (old, new) in enumerate(
                    zip(before_cells, java_cells)):
                if old == new:
                    continue
                x = x0 + cell % nx
                yz = cell // nx
                z = z0 + yz % nz
                y = y0 + yz // nz
                mutations[(x, y, z)] = (old, new)
            if mutations != expected_block or magma_cells != java_cells:
                failures.append("raw: expected exactly one roof block mutation")
            else:
                evidence.append("raw:1 exact opacity-changing block mutation")
        except (OSError, ValueError, IndexError, struct.error) as exc:
            failures.append(f"could not validate skylight transition: {exc}")
        return (
            ("fail", "; ".join(failures))
            if failures else
            ("pass", "; ".join(evidence))
        )

